package com.code.aon.payroll.auxiliares.organismosyentidades;


import java.util.HashSet;
import java.util.Set;

import javax.persistence.CascadeType;
import javax.persistence.Column;
import javax.persistence.Entity;
import javax.persistence.Id;
import javax.persistence.OneToMany;
import javax.persistence.Table;

import com.code.aon.common.ITransferObject;
/**
 * Entidad generated by Expand 2.0.1
 */
@Entity
@Table(name="entidad")

public class Entidad  implements ITransferObject  {

     private String cdg;
     private String description;
 	 private Set<Sucursal> sucursales = new HashSet<Sucursal>();

    @Id     
    @Column(name="cdg", unique=true, nullable=false, length=4)
    public String getCdg() {
        return this.cdg;
    }
    
    public void setCdg(String cdg) {
        this.cdg = cdg;
    }
    

    @Column(name="descripcion", nullable=false, length=35)
    public String getDescription() {
        return this.description;
    }
    
    public void setDescription(String descripcion) {
        this.description = descripcion;
    }

	@OneToMany(mappedBy = "entidad", cascade={CascadeType.REMOVE})
	public Set<Sucursal> getSucursales() {
		return sucursales;
	}

	public void setSucursales(Set<Sucursal> sucursales) {
		this.sucursales = sucursales;
	}
	


}


